# ShopScope Commerce, Spring Boot and Microservices: client TOC content, built from COURSE-OUTLINE.md v2.2.
# Every session lists its labs with minutes; session length = labs + a short concept block and wrap-up.

CORE = [
 dict(name="Day 1 — From a plain-Java monolith to Spring Core", short="Day 1",
      blurb="ShopScope Commerce, the online store built across the whole programme, starts as a plain-Java monolith: the whole backend in one process, wired by hand, with a written register of its problems. Then Spring takes over the wiring, and configuration, events and aspects move out of the business code.",
      note="Demo 1's code is pre-built; its labs read, run, break and measure it. Lab 7 (the testing context) of Demo 3 is demonstrated rather than typed.",
      sessions=[
  S("S1", 70, "Demo 1", "ShopScope as a plain-Java monolith",
    "The whole backend in miniature, with no framework: seven modules behind the same /api contract the microservices will later serve, in-memory stores, a composition root made of \"new\", a hand-written properties loader, logging pasted into every method and a hand-rolled HTTP layer. It works. The session is about seeing why it will not keep working: the dependency arrows that should not exist, the untestable OrderService with its hidden gateway, the overselling bug when a payment fails after stock was decremented, and the problem register every later demo closes one line at a time.",
    "Lab 1 Tour: the seven modules and the arrows that should not exist (10)\nLab 2 The composition root: add one dependency and count the files you touch (15)\nLab 3 Try to unit-test OrderService (10)\nLab 4 The shared in-memory store and the overselling bug (15)\nLab 5 The problem register (10)"),
  S("S2", 90, "Demo 2 (part 1)", "The container takes over the wiring",
    "The composition root of Demo 1 becomes the container's job. Dependency injection by hand, then with the container: ApplicationContext, @Configuration and @Bean. Every way to define a bean: @Component and stereotypes with scanning, @Bean and @Import, XML (read it, for legacy code), FactoryBean and programmatic registration. Injection: constructor vs setter vs field, optional dependencies, @Primary and @Qualifier, a custom qualifier, injecting a List or Map (the discount-rule chain), ObjectProvider and @Lazy. OrderService becomes testable.",
    "Lab 1 The wiring problem, and dependency injection by hand (15)\nLab 2 The container: @Configuration and @Bean (20)\nLab 3 Every way to define a bean (25)\nLab 4 Injection: constructor, qualifiers, List and Map (25)"),
  S("S3", 80, "Demo 2 (part 2)", "Scopes, the bean lifecycle and post-processors",
    "Singleton vs prototype and the stateful-singleton bug; a prototype inside a singleton. The bean lifecycle traced end to end: instantiation, population, Aware interfaces, BeanPostProcessor before and after (where proxies appear), @PostConstruct, afterPropertiesSet, init methods, @PreDestroy and SmartLifecycle. BeanFactoryPostProcessor vs BeanPostProcessor, bean definition overriding, and circular dependencies.",
    "Lab 5 Scopes and the stateful singleton (15)\nLab 6 The lifecycle, traced end to end (25)\nLab 7 A BeanFactoryPostProcessor and a BeanPostProcessor (15)\nLab 8 Overriding and circular dependencies (10)"),
  S("S4", 95, "Demo 3", "Configuration, events and aspects move out of the business code",
    "Environment, @PropertySource, @Value and SpEL replace the hand-written properties loader. Profiles: tax rules per region (India, UK, US). @Conditional with a custom condition. Application events: OrderPlaced reaches the notification module without a direct call; @EventListener, ordering and async listeners. AOP: a proxy by hand, JDK vs CGLIB, @Aspect, pointcuts and @Around; the pasted timing and audit code becomes one @Audited aspect; and the self-invocation trap that explains why @Transactional and @Cacheable sometimes do nothing.",
    "Lab 1 Environment, @Value and SpEL replace the properties loader (15)\nLab 2 Profiles: tax rules per region (15)\nLab 3 A custom @Conditional (10)\nLab 4 Application events: OrderPlaced (15)\nLab 5 AOP: proxies, aspects and @Audited (25)\nLab 6 The self-invocation trap (5)")]),
 dict(name="Day 2 — Spring Boot, a REST API and PostgreSQL", short="Day 2",
      blurb="The monolith becomes a Spring Boot application with a starter of its own. Its hand-rolled HTTP layer becomes a REST API the storefront can rely on (stores and regions first, then products), with one error contract and live documentation, and the catalogue leaves memory for PostgreSQL with versioned migrations and localised data.",
      note="API versioning, ETags and the structured-logging lab are demonstrated rather than typed; their code is in the finished demo.",
      sessions=[
  S("S1", 90, "Demo 4", "The monolith becomes a Spring Boot application",
    "Adding Boot to the same project: the parent, starters, @SpringBootApplication taken apart. Auto-configuration: delete what Boot now provides, read the conditions report, override with @ConditionalOnMissingBean. Externalised configuration: application.yml, property-source order, profiles, @ConfigurationProperties records with validation. Our own auto-configuration in libs/shopscope-starter (request ids, a clock, the shopper session). ApplicationRunner, Actuator and the executable jar.",
    "Lab 1 Add Boot: parent, starters, @SpringBootApplication (20)\nLab 2 Auto-configuration and the conditions report (20)\nLab 3 Externalised configuration (15)\nLab 4 Write our own starter (20)\nLab 5 Actuator and the executable jar (10)"),
  S("S2", 95, "Demo 5", "The hand-rolled HTTP layer becomes a REST API",
    "A multi-module build: a parent POM and one Maven module per bounded context, with the dependency rules the modules may not break. Spring MVC under REST: DispatcherServlet, handler mapping, message converters. Resource design: URIs, methods, idempotency, status codes, and the /api contract we keep. Stores and the store context (country, language, currency) as the first resource, then product CRUD with ResponseEntity, Location headers, 204 and 404 replacing the HttpServer handlers. View records, MapStruct and hand-written mappers, Jackson 3, and .http request files.",
    "Lab 1 One Maven module per bounded context (15)\nLab 2 Spring MVC under REST, and resource design (15)\nLab 3 Stores and the store context (20)\nLab 4 Product CRUD replaces the HttpServer handlers (25)\nLab 5 View records and MapStruct (15)"),
  S("S3", 85, "Demo 6", "One error contract, and an API people can read",
    "Bean Validation on requests, groups and a custom constraint (@ValidSku). One error contract: ProblemDetail (RFC 9457) from @RestControllerAdvice, moved into the shared starter so every module, and later every service, answers the same way. Paging, sorting and filtering in the contract. API versioning with Spring Framework 7, OpenAPI 3 with springdoc and Swagger UI, and conditional requests with ETags.",
    "Lab 1 Bean Validation and a custom constraint (20)\nLab 2 One error contract with ProblemDetail (25)\nLab 3 Paging, sorting and filtering (15)\nLab 4 OpenAPI and Swagger UI (15)"),
  S("S4", 90, "Demo 7", "The catalogue leaves memory: Spring Data JPA on PostgreSQL",
    "JPA, Hibernate and Spring Data: who does what, and the infrastructure boundary that keeps JPA types out of the domain. The first @Entity. Flyway migrations and seed data, and why ddl-auto stays off. Localised names, descriptions and slugs per locale with fallback and slug routing. JpaRepository, derived queries, @Query (JPQL and native), paging, sorting and projections. Custom attributes as JSONB, and seeing the SQL.",
    "Lab 1 The first entity, and the boundary (20)\nLab 2 Flyway migrations and seed data (15)\nLab 3 Localised data and slug routing (20)\nLab 4 Repositories, derived queries and @Query (15)\nLab 5 Paging, projections and JSONB attributes (15)")]),
 dict(name="Day 3 — Relationships, search, transactions and the safety net", short="Day 3",
      blurb="The catalogue model gets relationships that perform, full-text search, facets and a composed product-listing endpoint. The order module moves to the database with carts, checkout and transactions that behave under concurrent load, and the overselling bug from Day 1 is fixed. The day closes with the minimum test suite every module keeps from here on.",
      note="JPA auditing and soft delete are demonstrated rather than typed. Testing is covered in depth in the two Testing add-on days; Demo 11 is the safety net the core needs.",
      sessions=[
  S("S1", 80, "Demo 8", "Relationships that perform",
    "Category tree, product, variants, images, reviews and store-to-product: @ManyToOne, @OneToMany, @ManyToMany and the owning side. The variant matrix and bundles (a product composed of products), cascades, orphanRemoval, equals and hashCode. The N+1 problem caught on the product list and fixed three ways: JOIN FETCH, @EntityGraph and DTO projections. Batch fetching, open-in-view off, LazyInitializationException explained, auditing and soft delete.",
    "Lab 1 The catalogue model and the owning side (25)\nLab 2 Variants, bundles and cascades (15)\nLab 3 Catch the N+1 (10)\nLab 4 Fix it three ways (20)"),
  S("S2", 85, "Demo 9", "Search, facets and the product listing",
    "Filters from the API to SQL with Specifications; store-scoped and category-subtree queries. Full-text search with tsvector, ranking and a generated column. Facets: counts per attribute, price ranges and post-filtering semantics. One composed /api/plp response (cards, facets, total, sort) and its caching. When PostgreSQL is not enough: OpenSearch as a read model, previewed.",
    "Lab 1 Specifications, store scope and category subtrees (20)\nLab 2 Full-text search with tsvector (20)\nLab 3 Facets and post-filtering (20)\nLab 4 The composed product-listing endpoint (15)"),
  S("S3", 100, "Demo 10", "Carts, checkout and the overselling bug, fixed",
    "The order module moves to PostgreSQL: cart and order aggregates on JPA, line items, a bundle as one unit, a Subscribe & Save line. The cart write model: quantities, shipping address, pickup vs delivery, shipping methods, discount codes, the summary. Cart rules as a rule chain with the List injection from Day 1. @Transactional at the service layer: what the proxy does, readOnly, rollback rules, propagation and isolation demonstrated; the Demo 1 overselling scenario replayed, and fixed. Two tabs, one cart: optimistic locking with @Version and a retry; pessimistic locking, and when. Checkout: the order number and idempotency key, and @TransactionalEventListener for \"order placed\".",
    "Lab 1 Cart and order aggregates on JPA (20)\nLab 2 The cart write model and cart rules (20)\nLab 3 @Transactional, propagation and isolation: the overselling bug, fixed (25)\nLab 4 Two tabs, one cart: optimistic and pessimistic locking (15)\nLab 5 Checkout, idempotency and transactional events (10)"),
  S("S4", 80, "Demo 11", "The safety net: tests every module keeps",
    "The test pyramid for a service and what belongs where. Unit tests with JUnit, Mockito and AssertJ, and test-data builders for carts and products. @WebMvcTest with MockMvcTester for a controller and the error contract. @DataJpaTest with Testcontainers and @ServiceConnection against a real PostgreSQL, and context caching so the suite stays fast.",
    "Lab 1 The pyramid for a service (10)\nLab 2 Unit tests and test-data builders (20)\nLab 3 Controller tests with @WebMvcTest (20)\nLab 4 Repository tests with Testcontainers (20)")]),
 dict(name="Day 4 — From monolith to microservices", short="Day 4",
      blurb="The modular monolith is split. The catalogue becomes the first service, extracted by hand with every consequence felt; the remaining modules follow as pre-built services, with orders on MySQL and customers on MongoDB, and a checkout that now spans four services. Configuration is centralised, services find each other, and one gateway exposes the /api contract. At the end of the day the Next.js storefront runs against the real system.",
      note="The extracted services of Demo 13 arrive pre-built, so the session stays on what is new: MySQL, MongoDB and the checkout across four services. Demos 14 and 15 share one session: config refresh in depth, OpenFeign and registry internals move to the Microservices in depth add-on.",
      sessions=[
  S("S1", 95, "Demo 12", "The first cut: the catalogue becomes a service",
    "Monolith vs modular monolith vs microservices; bounded contexts; database per service; the strangler pattern; the ShopScope target map. The catalog module becomes catalog-service with its own PostgreSQL database and the /api/products routes. The monolith calls it with RestClient (a product snapshot at checkout), then through an @HttpExchange interface. Timeouts, connection pools, a downstream ProblemDetail mapped to our own, correlation ids across processes, and running several processes locally.",
    "Lab 1 Architecture, not code (15)\nLab 2 Extract catalog-service (25)\nLab 3 RestClient, then an HTTP interface (20)\nLab 4 Timeouts and error mapping (15)\nLab 5 Correlation ids across processes (10)"),
  S("S2", 100, "Demo 13", "The monolith is gone: pricing, inventory, orders on MySQL, customers on MongoDB",
    "The remaining modules extracted the same way, pre-built. pricing-service and inventory-service on PostgreSQL: the scoped price on every card and line, stock per supply channel, availability badges, the stock gate, reservations. order-service on MySQL: the same Spring Data JPA, a different dialect, Flyway for MySQL, and the Day 3 locking test re-run on InnoDB (REPEATABLE READ vs READ COMMITTED). customer-service on MongoDB: why a customer is a document with an embedded address book, Spring Data MongoDB, @Document, MongoRepository and MongoTemplate, indexes, schema evolution without migrations, @DataMongoTest with Testcontainers. Checkout across four services, and what happens when step three fails.",
    "Lab 1 Pricing and inventory as services (15)\nLab 2 order-service on MySQL: dialect, Flyway, InnoDB locking (25)\nLab 3 customer-service on MongoDB (30)\nLab 4 Checkout across four services, and the failure (20)"),
  S("S3", 85, "Demos 14–15", "Every service reads its configuration from one place, and services find each other",
    "Spring Cloud Config Server backed by a Git repository: one file per service per profile, spring.config.import, fail-fast and retry, encrypted secrets and provider keys that never enter Git, @RefreshScope and feature flags. A Eureka discovery server, registrations, and client-side load balancing with a @LoadBalanced RestClient across two instances.",
    "Lab 1 Config Server from Git (20)\nLab 2 The client side, and secrets (15)\nLab 3 Refresh at runtime and feature flags (15)\nLab 4 Eureka and a load-balanced RestClient (25)"),
  S("S4", 85, "Demo 16", "One front door: the API gateway, and the storefront arrives",
    "Spring Cloud Gateway: the /api contract as routes, predicates and lb:// URIs. Filters: path rewriting, request ids, the shopper-session cookie, a custom global filter. CORS once at the edge, rate limiting with Redis, and one OpenAPI page aggregated for every service. The finished Next.js storefront runs against the gateway and browses the real catalogue. The problem register of Day 1 is empty.",
    "Lab 1 Routes through the gateway (25)\nLab 2 Filters and the shopper session (20)\nLab 3 CORS and rate limiting (15)\nLab 4 The storefront arrives (15)")]),
 dict(name="Day 5 — Security: Spring Security, JWT, securing the system, and Keycloak", short="Day 5",
      blurb="From the security filter chain to an identity service that issues JWTs, resource servers that validate them, the guest-to-customer session boundary, ownership rules, service-to-service credentials, and finally handing login over to Keycloak with OAuth2 and OpenID Connect.",
      note="Method security on the back-office endpoints and the OWASP API Security Top 10 review are demonstrated rather than typed.",
      sessions=[
  S("S1", 85, "Demo 17", "Who are you? The identity service and Spring Security fundamentals",
    "The filter chain on every request and what the default does. SecurityFilterChain as a bean; authentication vs authorisation. Users in PostgreSQL with UserDetailsService, BCrypt and DelegatingPasswordEncoder. Registration, e-mail uniqueness, password rules, the password-reset token and the e-mail-verification token. CSRF (when it matters, when a stateless API turns it off), CORS and security headers.",
    "Lab 1 What the default does (10)\nLab 2 Your own SecurityFilterChain (15)\nLab 3 Users in the database (25)\nLab 4 Registration, reset and verification tokens (20)\nLab 5 CSRF, CORS and headers (10)"),
  S("S2", 100, "Demo 18", "Tokens everywhere: JWT, resource servers and the session boundary",
    "A JWT decoded: header, claims, signature; HMAC vs RSA. Login that issues an RS256 token with JwtEncoder and a JWKS endpoint. The other services as OAuth2 resource servers validating via the JWKS URI. Roles and scopes from claims to authorities. Refresh tokens with rotation and reuse detection, stored hashed. The session boundary: the anonymous cart merged into the customer's cart on login, with a merge mode, and sign-out. Logout, revocation and the bad-token checklist.",
    "Lab 1 Decode a JWT (10)\nLab 2 A login that issues RS256 tokens, and JWKS (25)\nLab 3 Services as resource servers (20)\nLab 4 Roles from claims (10)\nLab 5 Refresh tokens with rotation (15)\nLab 6 Guest to customer: the cart merge (15)"),
  S("S3", 85, "Demo 19", "Securing the calls between services",
    "JWT validation at the gateway and token relay to services. Ownership: customers see only their own orders, addresses and shopping lists. Service-to-service calls with client credentials, and never forwarding a user token blindly. Security tests with @WithMockUser and the jwt() post-processor. The OWASP API Security Top 10 checked against ShopScope.",
    "Lab 1 JWT at the gateway, and token relay (25)\nLab 2 Ownership: only your own orders (20)\nLab 3 Client credentials between services (20)\nLab 4 Security tests (15)"),
  S("S4", 90, "Demo 20", "Login leaves the building: Keycloak, OAuth2 and OpenID Connect",
    "Why teams stop running their own login. OAuth2 roles and flows, and OIDC. Keycloak in a container: realm, clients and roles imported from JSON. Swap the issuer: the services trust Keycloak and the identity service retires. The storefront signs in with authorization code + PKCE through the gateway as a backend-for-frontend (oauth2Login, TokenRelay, an httpOnly cookie), compared with a public SPA client. Client credentials for back-office jobs and mapping realm roles.",
    "Lab 1 OAuth2 flows and OIDC (10)\nLab 2 Keycloak in a container (20)\nLab 3 Swap the issuer (20)\nLab 4 The storefront signs in with PKCE (25)\nLab 5 Client credentials and realm roles (10)")]),
]

